# Teljes hibrid ChatGPT-klón (FastAPI + SSE + Cerebras GPT-OSS-120B + OpenAI Responses + Exa AI) – csak main.py és index.html

Az alábbi két fájl egy teljes, futtatható, minimalista, mégis robusztus példát ad egy PWA-s, sötét módú, ChatGPT iOS-stílusú chat UI-hoz FastAPI backenddel, SSE streameléssel, és integrációval a Cerebras GPT-OSS-120B (OpenAI-kompatibilis endpoint), OpenAI Responses API, valamint az Exa AI Deep Search/WebSets/RAG funkciókhoz.[1][2][3][4][5]

A megoldás:
- Backend: FastAPI, SSE stream a modellekből és a RAG/Exa folyamatokból, WebSet API, Deep Search, Link-alapú keresés, Tool calling (OpenAI Responses + Exa), RAG quickstart pipeline.[1][5]
- Frontend: PWA, iOS ChatGPT dark UI, modellváltó, gombok: Mély keresés, Link-alapú keresés, WebSet készítés; widgetes eredmények, állapotjelző; tokenenként frissülő stream.[1]

Megjegyzés a külső szolgáltatókhoz:
- Exa API: lásd docs.exa.ai – Search, Contents, Research, Websets, Answer, RAG quickstart, Responses-integrációs minták.[1][5]
- Cerebras GPT-OSS-120B: OpenAI API-kompatibilis inference (3,000 toks/sec benchmark); itt OpenAI-kompatibilis HTTP-t használunk, a BASE_URL-t és KEY-t környezeti változókból olvassuk.[2][4][3]
- OpenAI Responses API: vegyes tool-calling Exa-val; a tools szekcióban regisztrált Exa műveleteket a backend valósítja meg.[1]

Környezeti változók (példa):
- EXA_API_KEY
- OPENAI_API_KEY
- OPENAI_BASE_URL (pl. normál OpenAI vagy Cerebras OpenAI-kompatibilis endpoint a GPT-OSS-120B-hez)
- DEFAULT_MODEL_CEREBRAS=gpt-oss-120b
- DEFAULT_MODEL_OPENAI=gpt-5 (példa, a tényleges modellnév platformtól függhet)

Dependencies (pip):
- fastapi, uvicorn, sse-starlette, httpx, pydantic, python-multipart

Indítás:
- uvicorn main:app --reload

------------------------------------------------------------
main.py
------------------------------------------------------------
```python
import os
import json
import time
import uuid
import asyncio
from typing import AsyncGenerator, Dict, Any, List, Optional

import httpx
from fastapi import FastAPI, Request, Body, Query, Form
from fastapi.responses import HTMLResponse
from sse_starlette.sse import EventSourceResponse
from pydantic import BaseModel, Field

# Környezeti változók
EXA_API_KEY = os.getenv("EXA_API_KEY", "")
OPENAI_API_KEY = os.getenv("OPENAI_API_KEY", "")
OPENAI_BASE_URL = os.getenv("OPENAI_BASE_URL", "")

DEFAULT_MODEL_CEREBRAS = os.getenv("DEFAULT_MODEL_CEREBRAS", "gpt-oss-120b")
DEFAULT_MODEL_OPENAI = os.getenv("DEFAULT_MODEL_OPENAI", "gpt-5")
TIMEOUT = httpx.Timeout(60.0, read=300.0)

# Exa API alapok (docs.exa.ai)
EXA_BASE = ""
EXA_HEADERS = {"x-api-key": EXA_API_KEY, "content-type": "application/json"}

app = FastAPI(title="Hybrid ChatGPT Clone (Cerebras+OpenAI+Exa)", version="1.0")


# ---------- Pydantic modellek ----------

class ChatMessage(BaseModel):
    role: str
    content: str


class ChatRequest(BaseModel):
    model: str = Field(..., description="Cerebras GPT-OSS-120B | OpenAI GPT-5 | search-exa")
    messages: List[ChatMessage]
    webset_id: Optional[str] = None
    use_rag: bool = False


class DeepSearchRequest(BaseModel):
    query: str


class LinkSearchRequest(BaseModel):
    url: str


class WebSetCreateRequest(BaseModel):
    links: List[str]
    name: Optional[str] = None
    description: Optional[str] = None


# ---------- Util: SSE segédfüggvény ----------

def sse_format(data: Dict[str, Any]) -> str:
    return f"data: {json.dumps(data, ensure_ascii=False)}\n\n"


# ---------- Exa API hívások (Deep Search, Contents, Research, WebSets, Answer) ----------

async def exa_search(query: str) -> Dict[str, Any]:
    # /search – egyszerű keresés
    # 
    payload = {"query": query, "num_results": 5}
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.post(f"{EXA_BASE}/search", headers=EXA_HEADERS, json=payload)
        r.raise_for_status()
        return r.json()


async def exa_contents(urls: List[str]) -> Dict[str, Any]:
    # /contents – letisztított tartalom
    payload = {"ids_or_urls": urls, "include_html": False}
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.post(f"{EXA_BASE}/contents", headers=EXA_HEADERS, json=payload)
        r.raise_for_status()
        return r.json()


async def exa_research(query: str) -> Dict[str, Any]:
    # /research – strukturált mély kutatás, hivatkozásokkal
    payload = {"query": query, "max_depth": 2}
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.post(f"{EXA_BASE}/research", headers=EXA_HEADERS, json=payload)
        r.raise_for_status()
        return r.json()


async def exa_answer(question: str, webset_id: Optional[str] = None) -> Dict[str, Any]:
    # /answer – direkt válasz hivatkozásokkal; webset fókusz opció
    payload = {"question": question}
    if webset_id:
        payload["webset_id"] = webset_id
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.post(f"{EXA_BASE}/answer", headers=EXA_HEADERS, json=payload)
        r.raise_for_status()
        return r.json()


# WebSets API (create, get, list items stb.) – alap quickstart
async def exa_webset_create(links: List[str], name: Optional[str], description: Optional[str]) -> Dict[str, Any]:
    payload = {
        "name": name or f"WebSet {int(time.time())}",
        "description": description or "User provided links",
        "items": [{"url": u} for u in links],
    }
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.post(f"{EXA_BASE}/websets", headers=EXA_HEADERS, json=payload)
        r.raise_for_status()
        return r.json()


async def exa_webset_get(webset_id: str) -> Dict[str, Any]:
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.get(f"{EXA_BASE}/websets/{webset_id}", headers=EXA_HEADERS)
        r.raise_for_status()
        return r.json()


async def exa_webset_items(webset_id: str, limit: int = 20) -> Dict[str, Any]:
    params = {"limit": limit}
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.get(f"{EXA_BASE}/websets/{webset_id}/items", headers=EXA_HEADERS, params=params)
        r.raise_for_status()
        return r.json()


# ---------- OpenAI-kompatibilis Chat/Responses API (Cerebras GPT-OSS-120B + OpenAI GPT-5) ----------

async def openai_chat_stream(model: str, messages: List[Dict[str, str]]) -> AsyncGenerator[str, None]:
    # Chat Completions stream (OpenAI API kompatibilis)
    url = f"{OPENAI_BASE_URL}/chat/completions"
    headers = {"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"}
    payload = {
        "model": model,
        "messages": messages,
        "stream": True,
        # Célszerű a tool-calling engedélyezéséhez a Responses API-t használni.
    }
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        async with client.stream("POST", url, headers=headers, json=payload) as r:
            r.raise_for_status()
            async for line in r.aiter_lines():
                if not line:
                    continue
                if line.startswith("data: "):
                    data = line[len("data: "):]
                    if data == "[DONE]":
                        break
                    yield data


async def openai_responses_stream(
    model: str,
    messages: List[Dict[str, Any]],
    tools: Optional[List[Dict[str, Any]]] = None,
    metadata: Optional[Dict[str, Any]] = None,
) -> AsyncGenerator[Dict[str, Any], None]:
    # Responses API stream – tool calling integrációhoz
    url = f"{OPENAI_BASE_URL}/responses"
    headers = {"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"}
    payload: Dict[str, Any] = {
        "model": model,
        "input": messages,
        "stream": True,
    }
    if tools:
        payload["tools"] = tools
    if metadata:
        payload["metadata"] = metadata

    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        async with client.stream("POST", url, headers=headers, json=payload) as r:
            r.raise_for_status()
            async for line in r.aiter_lines():
                if not line or not line.startswith("data:"):
                    continue
                data = line[len("data:"):].strip()
                if data == "[DONE]":
                    break
                try:
                    yield json.loads(data)
                except Exception:
                    continue


# ---------- SSE végpontok ----------

@app.get("/", response_class=HTMLResponse)
async def root():
    # statikus HTML-t szolgáljuk ki
    with open("index.html", "r", encoding="utf-8") as f:
        return HTMLResponse(f.read())


@app.post("/api/deep_search")
async def api_deep_search(req: DeepSearchRequest):
    result = await exa_research(req.query)
    return result  # JSON; Frontend widget kártyákhoz forrás


@app.post("/api/link_search")
async def api_link_search(req: LinkSearchRequest):
    # URL tartalom + hasonlók felkutatása (Contents + FindSimilar)
    contents = await exa_contents([req.url])
    similar = {}
    # opcionális: find similar
    payload = {"url": req.url, "num_results": 5}
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.post(f"{EXA_BASE}/findSimilar", headers=EXA_HEADERS, json=payload)
        r.raise_for_status()
        similar = r.json()
    return {"contents": contents, "similar": similar}


@app.post("/api/webset_create")
async def api_webset_create(req: WebSetCreateRequest):
    webset = await exa_webset_create(req.links, req.name, req.description)
    return webset


@app.get("/api/webset/{webset_id}")
async def api_webset_get(webset_id: str):
    return await exa_webset_get(webset_id)


@app.get("/api/webset/{webset_id}/items")
async def api_webset_items(webset_id: str, limit: int = 20):
    return await exa_webset_items(webset_id, limit)


@app.post("/api/chat/stream")
async def api_chat_stream(request: Request, body: ChatRequest):
    """
    SSE stream:
    - model: "Cerebras GPT-OSS-120B" | "OpenAI GPT-5" | "search-exa"
    - use_rag: ha True, Exa Answer/WebSet fókusz
    - webset_id: RAG fókusz adott WebSet-re
    """

    async def event_gen() -> AsyncGenerator[str, None]:
        try:
            # Állapot: fogadás
            yield sse_format({"type": "status", "message": "Csatlakozás…"})
            model_name = body.model
            msgs = [{"role": m.role, "content": m.content} for m in body.messages]

            # RAG quickstart: ha bekapcsolt és van user kérdés
            if body.use_rag:
                user_q = ""
                for m in reversed(body.messages):
                    if m.role == "user":
                        user_q = m.content
                        break
                if user_q:
                    yield sse_format({"type": "status", "message": "RAG: releváns tartalom keresése (Exa)…"})
                    rag_ans = await exa_answer(user_q, body.webset_id)
                    # Illesszük a kontextust a prompt elé (system)
                    context_snippets = []
                    if "citations" in rag_ans:
                        for c in rag_ans["citations"][:5]:
                            context_snippets.append(f"- {c.get('title','')} ({c.get('url','')})")
                    context_text = "Releváns hivatkozások:\n" + "\n".join(context_snippets) if context_snippets else ""
                    msgs = [{"role": "system", "content": f"Használd ezeket a releváns hivatkozásokat:\n{context_text}"}] + msgs
                    yield sse_format({"type": "widget", "kind": "rag_citations", "data": rag_ans})

            # Modell kiválasztás
            if model_name == "Cerebras GPT-OSS-120B":
                chosen_model = DEFAULT_MODEL_CEREBRAS  # gpt-oss-120b
                yield sse_format({"type": "status", "message": "Cerebras stream indul…"})
                async for chunk in openai_chat_stream(chosen_model, msgs):
                    # chunk: OpenAI stream delta JSON
                    yield f"data: {chunk}\n\n"  # áteresztjük a delta-t
                yield sse_format({"type": "done"})

            elif model_name == "OpenAI GPT-5":
                # Tool calling integráció a Responses API-val – regisztrálunk Exa toolokat
                tools = [
                    {
                        "type": "function",
                        "function": {
                            "name": "exa_search",
                            "description": "Keresés az Exa AI-val (Top-5).",
                            "parameters": {"type": "object", "properties": {"query": {"type": "string"}}, "required": ["query"]},
                        },
                    },
                    {
                        "type": "function",
                        "function": {
                            "name": "exa_answer",
                            "description": "Exa közvetlen válasz hivatkozásokkal.",
                            "parameters": {"type": "object", "properties": {"question": {"type": "string"}, "webset_id": {"type": "string"}}, "required": ["question"]},
                        },
                    },
                ]
                # Messages formátum Responses API-hoz:
                inputs = [{"role": m["role"], "content": m["content"]} for m in msgs]

                yield sse_format({"type": "status", "message": "OpenAI Responses stream indul…"})
                async for ev in openai_responses_stream(DEFAULT_MODEL_OPENAI, inputs, tools=tools):
                    # Ha tool call jön, a backenden lefuttatjuk és visszaszúrjuk a streambe
                    if "type" in ev and ev["type"] == "response.output_text.delta":
                        # Szöveg delta
                        yield sse_format({"type": "delta", "text": ev.get("delta", "")})

                    if "type" in ev and ev["type"] == "response.tool_call":
                        # Tool hívás
                        fn = ev.get("name")
                        args = ev.get("arguments", {})
                        tool_result = None
                        if fn == "exa_search":
                            q = args.get("query", "")
                            tool_result = await exa_search(q)
                        elif fn == "exa_answer":
                            q = args.get("question", "")
                            ws = args.get("webset_id")
                            tool_result = await exa_answer(q, ws)
                        # Visszaküldjük mint widget + tool_result
                        yield sse_format({"type": "widget", "kind": fn, "data": tool_result})

                yield sse_format({"type": "done"})

            elif model_name == "Keresés (Exa AI)":
                # Csak keresés és widget beszúrás
                user_q = ""
                for m in reversed(body.messages):
                    if m.role == "user":
                        user_q = m.content
                        break
                if not user_q:
                    yield sse_format({"type": "error", "message": "Nincs felhasználói kérdés a kereséshez."})
                else:
                    yield sse_format({"type": "status", "message": "Mély keresés indul (Exa Research)…"})
                    research = await exa_research(user_q)
                    yield sse_format({"type": "widget", "kind": "deep_search", "data": research})
                yield sse_format({"type": "done"})

            else:
                yield sse_format({"type": "error", "message": f"Ismeretlen modell: {model_name}"})

        except httpx.HTTPStatusError as e:
            yield sse_format({"type": "error", "message": f"HTTP hiba: {e.response.status_code} - {e.response.text}"})
        except Exception as e:
            yield sse_format({"type": "error", "message": f"Hiba: {str(e)}"})

    return EventSourceResponse(event_gen(), media_type="text/event-stream")
```

