# --- Egyszerű IP alapú leaky-bucket limitelés (DoS védelem) ---
RATE_LIMIT_MAX = 120  # esemény/perc
RATE_WINDOW_SEC = 60
_buckets: Dict[str, deque] = {}

def rate_limit_ok(ip: str) -> bool:
    now = time.time()
    dq = _buckets.setdefault(ip, deque())
    while dq and now - dq[0] > RATE_WINDOW_SEC:
        dq.popleft()
    if len(dq) >= RATE_LIMIT_MAX:
        return False
    dq.append(now)
    return True

# --- Pydantic modellek ---
