    .topbar { display: flex; align-items: center; gap: 12px; padding: 12px 16px; background: var(--panel-2); border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 5; }
    .title { font-weight: 600; }
    .model { margin-left: auto; background: var(--panel); border: 1px solid var(--border); color: var(--text); padding: 8px 10px; border-radius: 10px; }
    .chat { padding: 16px; overflow-y: auto; }
    .bubble { max-width: 780px; margin: 0 auto 12px auto; display: flex; gap: 10px; }
    .bubble .msg { background: var(--panel); border: 1px solid var(--border); padding: 12px 14px; border-radius: 14px; line-height: 1.5; white-space: pre-wrap; }
    .bubble.user .msg { background: #0e1520; border-color: #1f2434; }
    .bubble.assistant .msg { background: var(--panel); }
    .bubble.system .msg { background: #0a0d12; color: var(--muted); }
    .widget { background: var(--card); border: 1px solid var(--border); padding: 10px; border-radius: 12px; margin-top: 6px; }
    .status { color: var(--muted); font-size: 12px; margin-top: 6px; }
    .inputbar { padding: 12px 16px; border-top: 1px solid var(--border); background: var(--panel-2); }
    .inputrow { max-width: 820px; margin: 0 auto; display: grid; grid-template-columns: 1fr auto auto auto; gap: 8px; }
    textarea { resize: none; height: 48px; padding: 12px; border-radius: 12px; border: 1px solid var(--border); background: var(--panel); color: var(--text); outline: none; }
    button { height: 48px; padding: 0 12px; border-radius: 12px; border: 1px solid var(--border); background: var(--panel); color: var(--text); cursor: pointer; }
    button:hover { border-color: var(--accent); }
    .pill { font-size: 14px; }
    .badge { display: inline-block; padding: 2px 8px; border-radius: 999px; background: #0e1b14; border: 1px solid #1e2e2a; color: #7ee0c4; font-size: 12px; }
    .cards { display: grid; gap: 8px; }
    .card { border: 1px solid var(--border); background: var(--panel); padding: 10px; border-radius: 10px; }
    a { color: #7dd3fc; text-decoration: none; }
    .row { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
    .small { font-size: 12px; color: var(--muted); }
  </style>
</head>
<body>
  <div class="app">
    <div class="topbar">
      <div class="title">Hibrid Chat</div>
      <select id="model" class="model">
        <option>Cerebras GPT-OSS-120B</option>
        <option>OpenAI GPT-5</option>
        <option>Keresés (Exa AI)</option>
      </select>
    </div>

    <div id="chat" class="chat"></div>

    <div class="inputbar">
      <div class="inputrow">
        <textarea id="input" placeholder="Írj be egy kérdést… (Shift+Enter új sor)"></textarea>
        <button class="pill" id="btn-deep">🔍 Mély keresés</button>
        <button class="pill" id="btn-link">🌐 Link-alapú</button>
        <button class="pill" id="btn-webset">📂 WebSet</button>
      </div>
      <div class="row" style="max-width:820px; margin:6px auto 0;">
        <label class="small"><input type="checkbox" id="use_rag"> RAG (Exa Answer/WebSet)</label>
        <input id="webset_id" placeholder="WebSet ID (opcionális)" style="flex:1; height:32px; padding:6px; border-radius:10px; border:1px solid var(--border); background:var(--panel); color:var(--text);" />
        <span class="small">Modellváltó a felső menüben.</span>
      </div>
    </div>
  </div>

  <script>
    // Egyszerű POST-os SSE polyfill fetch streammel
    class EventSourcePolyfill {
      constructor(url, options) {
        this.url = url; this.options = options || {};
        this.controller = new AbortController();
        this.listeners = { message: [], error: [] };
        this._start();
      }
      _start() {
        fetch(this.url, {
          method: this.options.method || 'GET',
          headers: { 'Content-Type': 'application/json' },
          body: this.options.body,
          signal: this.controller.signal,
        }).then(async res => {
          if (!res.ok) throw new Error(`HTTP ${res.status}`);
          const reader = res.body.getReader();
          const decoder = new TextDecoder();
          let buf = '';
          while (true) {
            const { value, done } = await reader.read();
            if (done) break;
            buf += decoder.decode(value, { stream: true });
            let idx;
            while ((idx = buf.indexOf('\n\n')) >= 0) {
              const chunk = buf.slice(0, idx);
              buf = buf.slice(idx + 2);
              if (chunk.startsWith('data:')) {
                const payload = chunk.slice(5).trim();
                this._emit('message', { data: payload });
              }
            }
          }
        }).catch(err => this._emit('error', err));
      }
      close() { this.controller.abort(); }
      set onmessage(fn) { this.listeners.message = [fn]; }
      set onerror(fn) { this.listeners.error = [fn]; }
      addEventListener(type, fn) { (this.listeners[type] ||= []).push(fn); }
      _emit(type, ev) { for (const fn of this.listeners[type] || []) fn(ev); }
    }

    // UI elemek
    const chat = document.getElementById('chat');
    const input = document.getElementById('input');
    const modelSel = document.getElementById('model');
    const btnDeep = document.getElementById('btn-deep');
    const btnLink = document.getElementById('btn-link');
    const btnWebSet = document.getElementById('btn-webset');
    const useRag = document.getElementById('use_rag');
    const websetIdEl = document.getElementById('webset_id');

    let history = [];

    function addBubble(role, content) {
      const wrap = document.createElement('div');
      wrap.className = 'bubble ' + role;
      const msg = document.createElement('div');
      msg.className = 'msg';
      msg.textContent = content;
      wrap.appendChild(msg);
      chat.appendChild(wrap);
      chat.scrollTop = chat.scrollHeight;
      return msg;
    }

    function addWidget(title, data) {
      const wrap = document.createElement('div');
      wrap.className = 'widget';
      const h = document.createElement('div');
      h.innerHTML = `<span class="badge">${title}</span>`;
      wrap.appendChild(h);
      const pre = document.createElement('pre');
      pre.textContent = JSON.stringify(data, null, 2);
      wrap.appendChild(pre);
      chat.appendChild(wrap);
      chat.scrollTop = chat.scrollHeight;
    }

    function addStatus(text) {
      const d = document.createElement('div');
      d.className = 'status';
      d.textContent = text;
      chat.appendChild(d);
      chat.scrollTop = chat.scrollHeight;
      return d;
    }

    function lastAssistantBubble() {
      const nodes = chat.querySelectorAll('.bubble.assistant .msg');
      return nodes[nodes.length - 1] || null;
    }

    async function sendChat() {
      const text = input.value.trim();
      if (!text) return;
      input.value = '';

      // User
      addBubble('user', text);
      history.push({ role: 'user', content: text });

      // Assistant placeholder
      addBubble('assistant', '');
      const assistantNode = lastAssistantBubble();

      const body = {
        model: modelSel.value,
        messages: history,
        use_rag: !!useRag.checked,
        webset_id: websetIdEl.value || null
      };

      const es = new EventSourcePolyfill('/api/chat/stream', { method: 'POST', body: JSON.stringify(body) });

      es.onmessage = (e) => {
        try {
          const data = JSON.parse(e.data);
          if (data.type === 'status') {
            addStatus(data.message);
          } else if (data.type === 'delta') {
            assistantNode.textContent += data.text || '';
          } else if (data.type === 'widget') {
            addWidget(data.kind, data.data);
          } else if (data.type === 'done') {
            history.push({ role: 'assistant', content: assistantNode.textContent });
            es.close();
          } else if (data.type === 'error') {
            addStatus('Hiba: ' + (data.message || 'ismeretlen'));
            es.close();
          } else if (data.choices) {
            // OpenAI stream delta áteresztése (Cerebras/OpenAI)
            try {
              for (const ch of data.choices) {
                if (ch.delta && ch.delta.content) assistantNode.textContent += ch.delta.content;
              }
            } catch {}
          }
        } catch {}
      };

      es.onerror = () => {
        addStatus('SSE kapcsolat megszakadt.');
        es.close();
      };
    }

    // Enter küldés
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        sendChat();
      }
    });

    // Gombok
    btnDeep.addEventListener('click', async () => {
      const query = prompt('Mély keresés lekérdezés:');
      if (!query) return;
      addStatus('Keresés folyamatban…');
      const res = await fetch('/api/deep_search', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ query }) });
      const data = await res.json();
      addWidget('Mély keresés (Exa Research)', data);
    });

    btnLink.addEventListener('click', async () => {
      const url = prompt('Link (URL):');
      if (!url) return;
      addStatus('Link feldolgozása…');
      const res = await fetch('/api/link_search', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ url }) });
      const data = await res.json();
      addWidget('Link-alapú keresés', data);
    });

    btnWebSet.addEventListener('click', async () => {
      const linksRaw = prompt('Adj meg több linket, soronként egyet:');
      if (!linksRaw) return;
      const links = linksRaw.split('\n').map(s => s.trim()).filter(Boolean);
      if (!links.length) return;
      addStatus('WebSet létrehozása…');
      const res = await fetch('/api/webset_create', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ links }) });
      const data = await res.json();
      addWidget('WebSet létrehozva', data);
      if (data && data.id) websetIdEl.value = data.id;
    });

    // Kezdő üzenet
    addBubble('system', 'Üdv! Válassz modellt fent, írj üzenetet, vagy használd a kereső gombokat.\n- RAG: a modell a releváns webes hivatkozásokra támaszkodik.\n- WebSet ID: adott linkhalmazra fókuszálhat a RAG.');

    // PWA service worker (két fájl limit megtartása: SW-t Blob-ból regisztráljuk)
    if ('serviceWorker' in navigator) {
      const swCode = `
        const CACHE = 'hychat-v1';
        const ASSETS = ['/',];
        self.addEventListener('install', e => {
          e.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS)));
        });
        self.addEventListener('activate', e => {
          e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k!==CACHE).map(k => caches.delete(k)))));
        });
        self.addEventListener('fetch', e => {
          const url = new URL(e.request.url);
          if (e.request.method === 'GET' && (url.origin === location.origin)) {
            e.respondWith(
              caches.match(e.request).then(r => r || fetch(e.request).then(resp => {
                const respClone = resp.clone();
                caches.open(CACHE).then(c => c.put(e.request, respClone));
                return resp;
              }).catch(() => caches.match('/')))
            );
          }
        });
      `;
      const blob = new Blob([swCode], { type: 'text/javascript' });
      const swUrl = URL.createObjectURL(blob);
      navigator.serviceWorker.register(swUrl).catch(()=>{});
    }
  </script>
</body>
</html>
