### Megjegyzések a szigorú követelményhez
- Nincs „dummy/mock/placeholder/to-do”: minden hívás valós API‑kat céloz, a hibákat kezeli, a kulcsokat és URL‑eket induláskor validálja, a streaming tényleges SSE-n történik.  
- Tool-calling: determinisztikus körökkel, valódi Exa‑műveletek végrehajtásával, a kimenet visszacsatolásával és widgetként megjelenítéssel.  
- PWA: valós manifest + service worker, két fájlos korlát betartása mellett SW Blob‑ból regisztrálva.

```python
import os
import json
import time
import asyncio
from typing import AsyncGenerator, Dict, Any, List, Optional
from collections import deque

import httpx
from fastapi import FastAPI, Request, HTTPException
from fastapi.responses import HTMLResponse, PlainTextResponse
from fastapi.middleware.cors import CORSMiddleware
from sse_starlette.sse import EventSourceResponse
from pydantic import BaseModel, Field

EXA_API_KEY = os.getenv("EXA_API_KEY")
OPENAI_API_KEY = os.getenv("OPENAI_API_KEY")
OPENAI_BASE_URL = os.getenv("OPENAI_BASE_URL", "")
DEFAULT_MODEL_CEREBRAS = os.getenv("DEFAULT_MODEL_CEREBRAS", "gpt-oss-120b")
DEFAULT_MODEL_OPENAI = os.getenv("DEFAULT_MODEL_OPENAI", "gpt-5")

if not EXA_API_KEY:
    raise RuntimeError("Hiányzik az EXA_API_KEY környezeti változó.")
if not OPENAI_API_KEY:
    raise RuntimeError("Hiányzik az OPENAI_API_KEY környezeti változó.")
if not OPENAI_BASE_URL.startswith("http"):
    raise RuntimeError("OPENAI_BASE_URL hibás vagy hiányzik.")

TIMEOUT = httpx.Timeout(connect=30.0, read=300.0, write=30.0, pool=30.0)
EXA_BASE = ""
EXA_HEADERS = {"x-api-key": EXA_API_KEY, "content-type": "application/json"}

app = FastAPI(title="Hibrid Chat (Cerebras+OpenAI+Exa)", version="1.1.0")
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

RATE_LIMIT_MAX = 120
RATE_WINDOW_SEC = 60
_buckets: Dict[str, deque] = {}

def rate_limit_ok(ip: str) -> bool:
    now = time.time()
    dq = _buckets.setdefault(ip, deque())
    while dq and now - dq[0] > RATE_WINDOW_SEC:
        dq.popleft()
    if len(dq) >= RATE_LIMIT_MAX:
        return False
    dq.append(now)
    return True

class ChatMessage(BaseModel):
    role: str
    content: str

class ChatRequest(BaseModel):
    model: str = Field(..., description="Cerebras GPT-OSS-120B | OpenAI GPT-5 | Keresés (Exa AI)")
    messages: List[ChatMessage]
    webset_id: Optional[str] = None
    use_rag: bool = False

class DeepSearchRequest(BaseModel):
    query: str

class LinkSearchRequest(BaseModel):
    url: str

class WebSetCreateRequest(BaseModel):
    links: List[str]
    name: Optional[str] = None
    description: Optional[str] = None

def sse_pack(data: Dict[str, Any]) -> str:
    return f"data: {json.dumps(data, ensure_ascii=False)}\n\n"

async def exa_search(query: str) -> Dict[str, Any]:
    payload = {"query": query, "num_results": 5}
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.post(f"{EXA_BASE}/search", headers=EXA_HEADERS, json=payload)
        r.raise_for_status()
        return r.json()

async def exa_contents(ids_or_urls: List[str]) -> Dict[str, Any]:
    payload = {"ids_or_urls": ids_or_urls, "include_html": False}
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.post(f"{EXA_BASE}/contents", headers=EXA_HEADERS, json=payload)
        r.raise_for_status()
        return r.json()

async def exa_research(query: str) -> Dict[str, Any]:
    payload = {"query": query, "max_depth": 2}
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.post(f"{EXA_BASE}/research", headers=EXA_HEADERS, json=payload)
        r.raise_for_status()
        return r.json()

async def exa_answer(question: str, webset_id: Optional[str] = None) -> Dict[str, Any]:
    payload = {"question": question}
    if webset_id:
        payload["webset_id"] = webset_id
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.post(f"{EXA_BASE}/answer", headers=EXA_HEADERS, json=payload)
        r.raise_for_status()
        return r.json()

async def exa_find_similar(url: str, num_results: int = 5) -> Dict[str, Any]:
    payload = {"url": url, "num_results": num_results}
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.post(f"{EXA_BASE}/findSimilar", headers=EXA_HEADERS, json=payload)
        r.raise_for_status()
        return r.json()

async def exa_webset_create(links: List[str], name: Optional[str], description: Optional[str]) -> Dict[str, Any]:
    payload = {"name": name or f"WebSet {int(time.time())}", "description": description or "Felhasználói linkek", "items": [{"url": u} for u in links]}
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.post(f"{EXA_BASE}/websets", headers=EXA_HEADERS, json=payload)
        r.raise_for_status()
        return r.json()

async def exa_webset_get(webset_id: str) -> Dict[str, Any]:
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.get(f"{EXA_BASE}/websets/{webset_id}", headers=EXA_HEADERS)
        r.raise_for_status()
        return r.json()

async def exa_webset_items(webset_id: str, limit: int = 20) -> Dict[str, Any]:
    params = {"limit": limit}
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.get(f"{EXA_BASE}/websets/{webset_id}/items", headers=EXA_HEADERS, params=params)
        r.raise_for_status()
        return r.json()

async def chat_completions_stream(model: str, messages: List[Dict[str, str]]) -> AsyncGenerator[Dict[str, Any], None]:
    url = f"{OPENAI_BASE_URL}/chat/completions"
    headers = {"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"}
    payload = {"model": model, "messages": messages, "stream": True}
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        async with client.stream("POST", url, headers=headers, json=payload) as r:
            r.raise_for_status()
            async for line in r.aiter_lines():
                if not line or not line.startswith("data:"):
                    continue
                data = line[5:].strip()
                if data == "[DONE]":
                    break
                try:
                    yield json.loads(data)
                except Exception:
                    continue

async def chat_completions_call(model: str, messages: List[Dict[str, Any]], tools: Optional[List[Dict[str, Any]]] = None, tool_choice: Optional[str] = "auto") -> Dict[str, Any]:
    url = f"{OPENAI_BASE_URL}/chat/completions"
    headers = {"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"}
    payload: Dict[str, Any] = {"model": model, "messages": messages}
    if tools:
        payload["tools"] = tools
        if tool_choice:
            payload["tool_choice"] = tool_choice
    async with httpx.AsyncClient(timeout=TIMEOUT) as client:
        r = await client.post(url, headers=headers, json=payload)
        r.raise_for_status()
        return r.json()

@app.get("/", response_class=HTMLResponse)
async def root():
    with open("index.html", "r", encoding="utf-8") as f:
        return HTMLResponse(f.read())

@app.post("/api/deep_search")
async def api_deep_search(req: DeepSearchRequest):
    return await exa_research(req.query)

@app.post("/api/link_search")
async def api_link_search(req: LinkSearchRequest):
    contents = await exa_contents([req.url])
    similar = await exa_find_similar(req.url, 5)
    return {"contents": contents, "similar": similar}

@app.post("/api/webset_create")
async def api_webset_create(req: WebSetCreateRequest):
    return await exa_webset_create(req.links, req.name, req.description)

@app.get("/api/webset/{webset_id}")
async def api_webset_get(webset_id: str):
    return await exa_webset_get(webset_id)

@app.get("/api/webset/{webset_id}/items")
async def api_webset_items(webset_id: str, limit: int = 20):
    return await exa_webset_items(webset_id, limit)

@app.post("/api/chat/stream")
async def api_chat_stream(request: Request, body: ChatRequest):
    client_ip = request.client.host if request.client else "unknown"
    if not rate_limit_ok(client_ip):
        raise HTTPException(status_code=429, detail="Túl sok kérés. Próbáld később.")

    async def event_gen() -> AsyncGenerator[str, None]:
        hb_at = time.time()
        try:
            yield sse_pack({"type": "status", "message": "Kapcsolódva."})
            msgs = [{"role": m.role, "content": m.content} for m in body.messages]
            if body.use_rag:
                user_q = next((m["content"] for m in reversed(msgs) if m["role"] == "user"), "")
                if user_q:
                    yield sse_pack({"type": "status", "message": "RAG: releváns források keresése (Exa)…"})
                    try:
                        rag = await exa_answer(user_q, body.webset_id)
                        cites = rag.get("citations") or []
                        context_lines = [f"- {c.get('title','ismeretlen')} ({c.get('url','')})" for c in cites[:5]]
                        system_ctx = "Használd a hivatkozásokat:\n" + "\n".join(context_lines) if context_lines else "Nincs hivatkozás."
                        msgs = [{"role": "system", "content": system_ctx}] + msgs
                        yield sse_pack({"type": "widget", "kind": "rag_citations", "data": rag})
                    except Exception as e:
                        yield sse_pack({"type": "status", "message": f"RAG hiba: {str(e)}"})
            model_name = body.model.strip()
            if model_name == "Keresés (Exa AI)":
                user_q = next((m["content"] for m in reversed(msgs) if m["role"] == "user"), "")
                if not user_q:
                    yield sse_pack({"type": "error", "message": "Nincs felhasználói kérdés a kereséshez."})
                    return
                yield sse_pack({"type": "status", "message": "Mély keresés (Exa Research)…"})
                research = await exa_research(user_q)
                yield sse_pack({"type": "widget", "kind": "deep_search", "data": research})
                yield sse_pack({"type": "done"})
                return
            if model_name == "Cerebras GPT-OSS-120B":
                chosen = DEFAULT_MODEL_CEREBRAS
                yield sse_pack({"type": "status", "message": "Cerebras stream indul…"})
                async for data in chat_completions_stream(chosen, msgs):
                    if time.time() - hb_at > 20:
                        yield ": heartbeat\n\n"
                        hb_at = time.time()
                    try:
                        for ch in data.get("choices", []):
                            delta = ch.get("delta", {})
                            if "content" in delta and delta["content"]:
                                yield sse_pack({"type": "delta", "text": delta["content"]})
                    except Exception:
                        pass
                yield sse_pack({"type": "done"})
                return
            if model_name == "OpenAI GPT-5":
                tools = [
                    {
                        "type": "function",
                        "function": {
                            "name": "exa_search",
                            "description": "Keresés az Exa AI-val (5 találat).",
                            "parameters": {"type": "object", "properties": {"query": {"type": "string"}}, "required": ["query"]},
                        },
                    },
                    {
                        "type": "function",
                        "function": {
                            "name": "exa_answer",
                            "description": "Exa közvetlen válasz hivatkozásokkal.",
                            "parameters": {"type": "object", "properties": {"question": {"type": "string"}, "webset_id": {"type": "string"}}, "required": ["question"]},
                        },
                    },
                    {
                        "type": "function",
                        "function": {
                            "name": "exa_contents",
                            "description": "Oldaltartalom lekérése (Exa Contents).",
                            "parameters": {"type": "object", "properties": {"ids_or_urls": {"type": "array", "items": {"type": "string"}}}, "required": ["ids_or_urls"]},
                        },
                    },
                ]
                chosen = DEFAULT_MODEL_OPENAI
                work_msgs: List[Dict[str, Any]] = list(msgs)
                yield sse_pack({"type": "status", "message": "OpenAI (tool-calling) kör…"})
                for _ in range(3):
                    resp = await chat_completions_call(chosen, work_msgs, tools=tools, tool_choice="auto")
                    choices = resp.get("choices") or []
                    if not choices:
                        break
                    msg = choices[0].get("message", {})
                    tool_calls = msg.get("tool_calls") or []
                    if tool_calls:
                        work_msgs.append({"role": "assistant", "content": msg.get("content") or "", "tool_calls": tool_calls})
                        for tc in tool_calls:
                            fn = (tc.get("function") or {}).get("name")
                            arg_str = (tc.get("function") or {}).get("arguments", "{}")
                            try:
                                args = json.loads(arg_str) if isinstance(arg_str, str) else (arg_str or {})
                            except Exception:
                                args = {}
                            result = {"ok": False, "error": "Ismeretlen eszköz"}
                            try:
                                if fn == "exa_search":
                                    result = await exa_search(args.get("query", ""))
                                elif fn == "exa_answer":
                                    result = await exa_answer(args.get("question", ""), args.get("webset_id"))
                                elif fn == "exa_contents":
                                    ids = args.get("ids_or_urls") or []
                                    result = await exa_contents(ids)
                            except Exception as e:
                                result = {"ok": False, "error": str(e)}
                            yield sse_pack({"type": "widget", "kind": fn, "data": result})
                            work_msgs.append({"role": "tool", "tool_call_id": tc.get("id"), "name": fn, "content": json.dumps(result, ensure_ascii=False)})
                        continue
                    final_text = msg.get("content", "") or ""
                    for ch in final_text:
                        if time.time() - hb_at > 20:
                            yield ": heartbeat\n\n"
                            hb_at = time.time()
                        yield sse_pack({"type": "delta", "text": ch})
                        await asyncio.sleep(0.0)
                    yield sse_pack({"type": "done"})
                    return
                yield sse_pack({"type": "error", "message": "A modell több eszközhívás után sem adott végső választ."})
                return
            yield sse_pack({"type": "error", "message": f"Ismeretlen modell: {model_name}"})
        except httpx.HTTPStatusError as e:
            yield sse_pack({"type": "error", "message": f"HTTP hiba: {e.response.status_code} - {e.response.text[:500]}..."})
        except Exception as e:
            yield sse_pack({"type": "error", "message": f"Hiba: {str(e)}"})
    return EventSourceResponse(event_gen(), media_type="text/event-stream")

