  <script>
    class EventSourcePolyfill{
      constructor(url,options){this.url=url;this.options=options||{};this.controller=new AbortController();this.listeners={message:[],error:[]};this._start()}
      _start(){fetch(this.url,{method:this.options.method||'GET',headers:{'Content-Type':'application/json'},body:this.options.body,signal:this.controller.signal}).then(async res=>{if(!res.ok)throw new Error(`HTTP ${res.status}`);const reader=res.body.getReader();const decoder=new TextDecoder();let buf='';while(true){const{value,done}=await reader.read();if(done)break;buf+=decoder.decode(value,{stream:true});let idx;while((idx=buf.indexOf('\n\n'))>=0){const chunk=buf.slice(0,idx);buf=buf.slice(idx+2);if(chunk.startsWith('data:')){const payload=chunk.slice(5).trim();this._emit('message',{data:payload})}}}}).catch(err=>this._emit('error',err))}
      close(){this.controller.abort()}
      set onmessage(fn){this.listeners.message=[fn]}
      set onerror(fn){this.listeners.error=[fn]}
      addEventListener(type,fn){(this.listeners[type]||=[]).push(fn)}
      _emit(type,ev){for(const fn of this.listeners[type]||[])fn(ev)}
    }
    const chat=document.getElementById('chat')
    const input=document.getElementById('input')
    const modelSel=document.getElementById('model')
    const btnDeep=document.getElementById('btn-deep')
    const btnLink=document.getElementById('btn-link')
    const btnWebSet=document.getElementById('btn-webset')
    const useRag=document.getElementById('use_rag')
    const websetIdEl=document.getElementById('webset_id')
    let history=[]
    function addBubble(role,content){const wrap=document.createElement('div');wrap.className='bubble '+role;const msg=document.createElement('div');msg.className='msg';msg.textContent=content;wrap.appendChild(msg);chat.appendChild(wrap);chat.scrollTop=chat.scrollHeight;return msg}
    function addWidget(title,data){const wrap=document.createElement('div');wrap.className='widget';const h=document.createElement('div');h.innerHTML=`<span class="badge">${title}</span>`;wrap.appendChild(h);const pre=document.createElement('pre');pre.textContent=JSON.stringify(data,null,2);wrap.appendChild(pre);chat.appendChild(wrap);chat.scrollTop=chat.scrollHeight}
    function addStatus(text){const d=document.createElement('div');d.className='status';d.textContent=text;chat.appendChild(d);chat.scrollTop=chat.scrollHeight;return d}
    function lastAssistantBubble(){const nodes=chat.querySelectorAll('.bubble.assistant .msg');return nodes[nodes.length-1]||null}
    async function sendChat(){
      const text=input.value.trim()
      if(!text)return
      input.value=''
      addBubble('user',text)
      history.push({role:'user',content:text})
      addBubble('assistant','')
      const assistantNode=lastAssistantBubble()
      const body={model:modelSel.value,messages:history,use_rag:!!useRag.checked,webset_id:websetIdEl.value||null}
      const es=new EventSourcePolyfill('/api/chat/stream',{method:'POST',body:JSON.stringify(body)})
      es.onmessage=(e)=>{
        try{
          const data=JSON.parse(e.data)
          if(data.type==='status'){addStatus(data.message)}
          else if(data.type==='delta'){assistantNode.textContent+=data.text||''}
          else if(data.type==='widget'){addWidget(data.kind,data.data)}
          else if(data.type==='done'){history.push({role:'assistant',content:assistantNode.textContent});es.close()}
          else if(data.type==='error'){addStatus('Hiba: '+(data.message||'ismeretlen'));es.close()}
          else if(data.choices){try{for(const ch of data.choices){if(ch.delta&&ch.delta.content)assistantNode.textContent+=ch.delta.content}}catch{}}
        }catch{}
      }
      es.onerror=()=>{addStatus('SSE kapcsolat megszakadt.');es.close()}
    }
