    btnWebSet.addEventListener('click',async()=>{const linksRaw=prompt('Adj meg több linket, soronként egyet:');if(!linksRaw)return;const links=linksRaw.split('\n').map(s=>s.trim()).filter(Boolean);if(!links.length)return;addStatus('WebSet létrehozása…');const res=await fetch('/api/webset_create',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({links})});const data=await res.json();addWidget('WebSet létrehozva',data);if(data&&data.id)websetIdEl.value=data.id})
    addBubble('system','Üdv! Válassz modellt fent, írj üzenetet, vagy használd a kereső gombokat.\n- RAG: a modell a releváns webes hivatkozásokra támaszkodik.\n- WebSet ID: adott linkhalmazra fókuszálhat a RAG.')
    if('serviceWorker' in navigator){
      const swCode=`const CACHE='hychat-v1';const ASSETS=['/'];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))))});
self.addEventListener('fetch',e=>{const url=new URL(e.request.url);if(e.request.method==='GET'&&(url.origin===location.origin)){e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request).then(resp=>{const respClone=resp.clone();caches.open(CACHE).then(c=>c.put(e.request,respClone));return resp}).catch(()=>caches.match('/'))))}});`
      const blob=new Blob([swCode],{type:'text/javascript'})
      const swUrl=URL.createObjectURL(blob)
      navigator.serviceWorker.register(swUrl).catch(()=>{})
    }
  </script>
